(function(){'use strict';function init(){document.querySelectorAll('.bmd-wac').forEach(function(root){var d={marketing:200,utility:800,auth:0,service:3000,numbers:1,marketingRate:.3217,utilityRate:.035,authRate:.035,serviceRate:.035,serviceFree:1000,platform:299,ai:120,markup:0,providerMessages:4000,setup:900};var fmt=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});function get(k){var el=root.querySelector('[data-wa="'+k+'"]');if(!el)return 0;var n=Number(el.value);return Number.isFinite(n)?Math.min(1000000000,Math.max(0,n)):0}function out(k,value){var el=root.querySelector('[data-wa-result="'+k+'"]');if(el)el.textContent=value}function update(){var numbers=Math.max(1,Math.floor(get('numbers'))),marketingCost=get('marketing')*get('marketingRate'),utilityCost=get('utility')*get('utilityRate'),authCost=get('auth')*get('authRate'),free=Math.min(get('service'),get('serviceFree')*numbers),paid=Math.max(0,get('service')-free),serviceCost=paid*get('serviceRate'),platformCost=get('platform'),aiCost=get('ai'),markupCost=get('markup')*get('providerMessages'),monthly=marketingCost+utilityCost+authCost+serviceCost+platformCost+aiCost+markupCost,annual=monthly*12+get('setup');[['marketingCost',marketingCost],['utilityCost',utilityCost],['authCost',authCost],['serviceCost',serviceCost],['platformCost',platformCost],['aiCost',aiCost],['markupCost',markupCost],['monthly',monthly],['year',annual],['effective',annual/12]].forEach(function(e){out(e[0],fmt.format(e[1]))});out('serviceInfo',new Intl.NumberFormat('pt-BR').format(free)+' mensagens de serviço consideradas na franquia; '+new Intl.NumberFormat('pt-BR').format(paid)+' cobradas pela Meta na simulação.');}root.querySelectorAll('input[data-wa]').forEach(function(i){i.addEventListener('input',update)});var reset=root.querySelector('.bmd-wac-reset');if(reset)reset.addEventListener('click',function(){Object.keys(d).forEach(function(k){var e=root.querySelector('[data-wa="'+k+'"]');if(e)e.value=d[k]});update()});update()})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();